-- Catálogo do site (gerado de src/data/content.ts por scripts/catalog-sql.mjs).
-- jobs.service_type_id e vehicles.category_id dependem destas linhas. Rodar de novo ao mudar o catálogo.

insert into service_types (id, name_pt, name_en, summary_pt, summary_en, description_pt, description_en,
  includes_pt, includes_en, ideal_for_pt, ideal_for_en, image_url, sort_order, published) values
  ('protecao-executiva', 'Proteção executiva', 'Executive protection', 'Agentes ao lado do protegido em agenda, reuniões, eventos e deslocamentos.', 'Agents alongside the principal at meetings, events and on the move.', 'Close protection no padrão das empresas globais de segurança. Agentes treinados acompanham o protegido durante toda a agenda, com presença discreta, leitura constante do ambiente e plano de contingência definido antes da operação começar.', 'Close protection to the standard of global security firms. Trained agents accompany the principal throughout the schedule, with a discreet presence, constant situational awareness and a contingency plan set before the operation begins.',
   array['Agentes armados ou desarmados', 'Análise de risco da agenda', 'Advance em locais e rotas', 'Comunicação por rádio entre a equipe', 'Atendimento em inglês']::text[], array['Armed or unarmed agents', 'Schedule risk assessment', 'Advance work on venues and routes', 'Radio communication across the team', 'Service in English']::text[], 'Executivos C-level, celebridades, atletas e visitantes estrangeiros.', 'C-level executives, celebrities, athletes and foreign visitors.', '/images/agent.jpg', 1, true),
  ('escolta-veicular', 'Escolta veicular', 'Vehicle escort', 'Veículo de apoio com agentes acompanhando cada deslocamento.', 'Support vehicle with agents shadowing every journey.', 'Um veículo de apoio segue o veículo principal com agentes preparados para reagir. A rota é estudada antes, com alternativas e pontos seguros mapeados, para que o deslocamento aconteça sem surpresas.', 'A support vehicle follows the principal vehicle with agents ready to respond. The route is studied in advance, with alternatives and safe points mapped, so the journey happens without surprises.',
   array['Veículo de apoio com agentes', 'Planejamento de rota e rotas alternativas', 'Opção de veículo principal blindado', 'Coordenação entre motoristas e equipe']::text[], array['Support vehicle with agents', 'Route and alternative-route planning', 'Armored principal vehicle option', 'Coordination between drivers and team']::text[], 'Deslocamentos de alto valor, comitivas e trajetos sensíveis.', 'High-value movements, delegations and sensitive routes.', '/images/convoy.jpg', 2, true),
  ('transporte-executivo', 'Transporte executivo bilíngue', 'Bilingual executive transport', 'Aeroporto, hotel e reuniões com motorista que fala inglês.', 'Airport, hotel and meetings with an English-speaking driver.', 'Motoristas executivos treinados em direção defensiva, que falam inglês e conhecem a rotina de quem viaja a trabalho. Recepção no aeroporto, transfers entre hotel e compromissos e diárias à disposição.', 'Executive drivers trained in defensive driving who speak English and understand business travel. Airport meet & greet, hotel-to-meeting transfers and full days on call.',
   array['Motorista bilíngue (PT/EN)', 'Recepção no aeroporto', 'Sedan, SUV, blindado ou van', 'Diária ou transfer avulso', 'Pontualidade e rota planejada']::text[], array['Bilingual driver (PT/EN)', 'Airport meet & greet', 'Sedan, SUV, armored or van', 'Day rate or single transfer', 'Punctuality and planned route']::text[], 'Hóspedes de hotéis de alto padrão e executivos em viagem.', 'Guests of high-end hotels and travelling executives.', '/images/driver.jpg', 3, true),
  ('eventos', 'Segurança para eventos', 'Event security', 'Cobertura de segurança e logística para eventos e comitivas.', 'Security and logistics coverage for events and delegations.', 'Planejamento e execução de segurança para eventos corporativos, esportivos e privados, com experiência em grandes eventos internacionais. Controle de acesso, proteção de convidados VIP e logística de chegada e saída.', 'Security planning and execution for corporate, sporting and private events, with experience at major international events. Access control, VIP guest protection and arrival and departure logistics.',
   array['Planejamento de segurança do evento', 'Proteção de convidados VIP', 'Logística de chegada e saída', 'Equipe dimensionada ao evento']::text[], array['Event security planning', 'VIP guest protection', 'Arrival and departure logistics', 'Team sized to the event']::text[], 'Eventos corporativos, esportivos, lançamentos e recepções privadas.', 'Corporate and sporting events, launches and private receptions.', '/images/event.jpg', 4, true),
  ('analise-de-risco', 'Advance e análise de risco', 'Advance & risk assessment', 'Reconhecimento prévio de locais, rotas e cenários antes da agenda.', 'Prior reconnaissance of venues, routes and scenarios before the schedule.', 'Antes de qualquer operação, o local é visitado, as rotas são testadas e os riscos são mapeados. O resultado é um plano claro, com contingências, que orienta a equipe e dá tranquilidade ao cliente.', 'Before any operation, venues are visited, routes are tested and risks are mapped. The result is a clear plan with contingencies that guides the team and reassures the client.',
   array['Visita prévia a locais', 'Mapeamento de rotas e pontos seguros', 'Hospitais e apoio de emergência mapeados', 'Relatório com plano de contingência']::text[], array['Prior venue visits', 'Route and safe-point mapping', 'Hospitals and emergency support mapped', 'Report with contingency plan']::text[], 'Agendas de visitantes estrangeiros, viagens corporativas e eventos.', 'Foreign visitor schedules, corporate trips and events.', '/images/planning.jpg', 5, true)
on conflict (id) do update set
  name_pt = excluded.name_pt, name_en = excluded.name_en, summary_pt = excluded.summary_pt, summary_en = excluded.summary_en,
  description_pt = excluded.description_pt, description_en = excluded.description_en, includes_pt = excluded.includes_pt,
  includes_en = excluded.includes_en, ideal_for_pt = excluded.ideal_for_pt, ideal_for_en = excluded.ideal_for_en,
  image_url = excluded.image_url, sort_order = excluded.sort_order;

insert into vehicle_categories (id, name_pt, name_en, description_pt, description_en, capacity, armored, image_url, sort_order, published) values
  ('sedan', 'Sedan executivo', 'Executive sedan', 'Discreto, para agendas urbanas.', 'Discreet, for city schedules.', 3, false, '/images/fleet/sedan.webp', 1, true),
  ('suv', 'SUV executivo', 'Executive SUV', 'Mais espaço e bagagem.', 'More room and luggage space.', 4, false, '/images/fleet/suv.webp', 2, true),
  ('suv-blindado', 'SUV blindado', 'Armored SUV', 'Blindagem para deslocamentos sensíveis.', 'Armored for sensitive journeys.', 4, true, '/images/fleet/suv-blindado.webp', 3, true),
  ('van', 'Van executiva', 'Executive van', 'Comitivas e grupos.', 'Delegations and groups.', 10, false, '/images/fleet/van.webp', 4, true)
on conflict (id) do update set
  name_pt = excluded.name_pt, name_en = excluded.name_en, description_pt = excluded.description_pt,
  description_en = excluded.description_en, capacity = excluded.capacity, armored = excluded.armored,
  image_url = excluded.image_url, sort_order = excluded.sort_order;
